// One test per first-release clause (ACCEPTANCE.md LARDER-001 to LARDER-013), through the public
// HTTP door of a real Worker with D1.
import test from 'node:test'
import assert from 'node:assert/strict'
import { installation, workshop, evidence, parse } from './harness.mjs'

const line = (order, itemId) => order.lines.find(l => l.itemId === itemId)
const avail = (s, itemId) => s.availability.find(a => a.itemId === itemId)

test('LARDER-001 items, variants, units and parties; ambiguous conversions are refused', async t => {
  const h = await installation(); t.after(() => h.close())
  const timber = await h.command('item.save', { sku: 'WAL-BLANK', name: 'Walnut blank', kind: 'buy', baseUnit: 'each', conversions: [{ unit: 'Bundle', factor: '10' }] })
  assert.deepEqual(timber.conversions, [{ unit: 'bundle', factor: '10' }])
  await h.command('item.save', { sku: 'X', name: 'X', baseUnit: 'each', conversions: [{ unit: 'box', factor: '12' }, { unit: 'Box', factor: '10' }] }, { error: 'AMBIGUOUS_UNIT' })
  await h.command('item.save', { sku: 'Y', name: 'Y', baseUnit: 'each', conversions: [{ unit: 'each', factor: '2' }] }, { error: 'AMBIGUOUS_UNIT' })
  await h.command('item.save', { sku: 'wal-blank', name: 'Dup', baseUnit: 'each' }, { error: 'DUPLICATE_SKU' })
  const large = await h.command('item.save', { sku: 'BRD-L', name: 'Board', kind: 'make', baseUnit: 'each', template: 'Board', attributes: { Size: 'Large' } })
  await h.command('item.save', { sku: 'BRD-S', name: 'Board', kind: 'make', baseUnit: 'each', template: 'Board', attributes: { Size: 'Small' } })
  await h.command('item.save', { sku: 'BRD-L2', name: 'Board', kind: 'make', baseUnit: 'each', template: 'Board', attributes: { Size: 'Large' } }, { error: 'DUPLICATE_VARIANT' })
  const supplier = await h.command('party.save', { name: 'Tasmanian Timber Co', kind: 'supplier', abn: '51 824 753 556' })
  await h.command('party.save', { name: 'tasmanian timber co', kind: 'customer' }, { error: 'DUPLICATE_PARTY' })
  await h.command('partyItem.save', { partyId: supplier.id, itemId: timber.id, partyCode: 'TT-40', price: '9.5', unit: 'bundle' })
  await h.command('partyItem.save', { partyId: supplier.id, itemId: large.id, partyCode: 'TT-40' }, { error: 'AMBIGUOUS_REFERENCE' })
  // Quantities in an undefined unit, or that would round, are refused.
  const customer = await h.command('party.save', { name: 'Harbour Kitchen Co', kind: 'customer' })
  await h.command('so.quote', { customerId: customer.id, promiseDate: '2026-11-01', lines: [{ itemId: timber.id, quantity: '1', unit: 'crate', unitPrice: '1' }] }, { error: 'UNKNOWN_UNIT' })
  const oil = await h.command('item.save', { sku: 'OIL', name: 'Oil', baseUnit: 'l', conversions: [{ unit: 'ml', factor: '0.001' }] })
  await h.command('so.quote', { customerId: customer.id, promiseDate: '2026-11-01', lines: [{ itemId: oil.id, quantity: '0.0005', unit: 'ml', unitPrice: '1' }] }, { error: 'INEXACT_CONVERSION' })
  // Once used, an item's units are fixed.
  await h.command('so.quote', { customerId: customer.id, promiseDate: '2026-11-01', lines: [{ itemId: timber.id, quantity: '2', unit: 'bundle', unitPrice: '1' }] })
  const s = await h.state()
  assert.equal(s.salesOrders[0].lines[0].quantity, '20')
  const current = s.items.find(i => i.id === timber.id)
  await h.command('item.save', { id: timber.id, version: current.version, sku: 'WAL-BLANK', name: 'Walnut blank', baseUnit: 'piece' }, { error: 'UNIT_FIXED' })
})

test('LARDER-002 opening stock by location with date, valuation basis and evidence', async t => {
  const h = await installation(); t.after(() => h.close())
  const loc = await h.command('location.save', { name: 'Workshop' })
  const item = await h.command('item.save', { sku: 'OAK', name: 'Oak blank', baseUnit: 'each' })
  await h.command('opening.record', { locationId: loc.id, countedOn: '2026-10-01', valuationBasis: 'supplier-invoice', countedBy: 'Olive', lines: [{ itemId: item.id, quantity: '5', unitCost: '7' }] }, { error: 'EVIDENCE' })
  const opening = await h.command('opening.record', { locationId: loc.id, countedOn: '2026-10-01', valuationBasis: 'supplier-invoice', countedBy: 'Olive', evidence: evidence(), lines: [{ itemId: item.id, quantity: '5', unitCost: '7.25', lot: 'OAK-0926' }] })
  assert.equal(opening.valuationBasis, 'supplier-invoice'); assert.equal(opening.countedOn, '2026-10-01'); assert.equal(opening.evidence.size, Buffer.byteLength('Bay A count sheet, 1 Oct 2026'))
  const file = await h.request(`/api/larder/attachments/${opening.evidence.id}`)
  assert.equal(await file.text(), 'Bay A count sheet, 1 Oct 2026')
  const s = await h.invariant()
  assert.deepEqual(s.positions.map(p => [p.quantity, p.status]), [['5', 'available']])
  assert.equal(s.movements[0].unitCost, '7.25'); assert.equal(s.lots[0].code, 'OAK-0926')
  await h.command('opening.record', { locationId: loc.id, countedOn: '2026-10-02', valuationBasis: 'standard-cost', countedBy: 'Olive', evidence: evidence(), lines: [{ itemId: item.id, quantity: '1', unitCost: '7' }] }, { error: 'OPENING_EXISTS' })
})

test('LARDER-003 versioned BOM and routing; released work keeps its revision', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const wo = await h.command('wo.draft', { itemId: w.board.id, quantity: '2', requiredBy: '2026-11-01', reason: 'Stock for markets' })
  const released = await h.command('wo.release', { workOrderId: wo.id, version: wo.version })
  assert.equal(released.bomRevision, 1)
  assert.deepEqual(released.routing.map(r => r.name), ['Plane and cut', 'Oil'])
  const rev2 = await h.command('bom.revise', { itemId: w.board.id, components: [{ itemId: w.timber.id, quantity: '1' }, { itemId: w.oil.id, quantity: '80', unit: 'ml' }], note: 'Heavier oil coat' })
  assert.equal(rev2.revision, 2)
  const s = await h.state()
  const pinned = s.workOrders.find(x => x.id === wo.id)
  assert.equal(pinned.bomRevision, 1)
  assert.equal(pinned.components.find(c => c.itemId === w.oil.id).required, '0.1')
  assert.deepEqual(s.boms.filter(b => b.itemId === w.board.id).map(b => [b.revision, b.status]), [[1, 'superseded'], [2, 'active']])
  const next = await h.command('wo.draft', { itemId: w.board.id, quantity: '1', requiredBy: '2026-11-02', reason: 'Next' })
  const r2 = await h.command('wo.release', { workOrderId: next.id, version: next.version })
  assert.equal(r2.bomRevision, 2); assert.equal(r2.components.find(c => c.itemId === w.oil.id).required, '0.08')
})

test('LARDER-004 quote and confirm an order; physical, reserved and expected stock stay separate', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const quote = await h.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-10-28', customerReference: 'HK-221', lines: [{ itemId: w.board.id, quantity: '10', unitPrice: '89' }] })
  assert.equal(quote.status, 'quote')
  let a = avail(await h.state(), w.board.id)
  assert.deepEqual([a.onHand, a.reserved, a.available], ['4', '0', '4'])
  const wo = await h.command('wo.draft', { itemId: w.board.id, quantity: '3', requiredBy: '2026-10-25', reason: 'Harbour order' })
  await h.command('wo.release', { workOrderId: wo.id, version: wo.version })
  const confirmed = await h.command('so.confirm', { orderId: quote.id, version: quote.version })
  assert.equal(confirmed.status, 'confirmed')
  assert.deepEqual(confirmed.reservation.map(r => [r.reserved, r.short]), [['4', '6']])
  a = avail(await h.state(), w.board.id)
  assert.deepEqual([a.onHand, a.reserved, a.available, a.expectedProduction, a.unreservedDemand, a.availableToPromise], ['4', '4', '0', '3', '6', '-3'])
})

test('LARDER-005 reservations are atomic: competing orders never consume the same stock', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const orders = []
  for (let i = 0; i < 6; i++) {
    const q = await h.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-10-28', lines: [{ itemId: w.board.id, quantity: '3', unitPrice: '89' }] })
    orders.push(await h.command('so.confirm', { orderId: q.id, version: q.version, reserve: false }))
  }
  const results = await Promise.all(orders.map(o => h.send('so.reserve', { orderId: o.id })))
  for (const r of results) assert.equal(r.res.status, 200, JSON.stringify(r.body))
  const s = await h.invariant()
  const reserved = s.reservations.filter(r => r.itemId === w.board.id).reduce((n, r) => n + parse(r.quantity), 0n)
  assert.equal(reserved, parse('4'))
  // A retry with the same identity returns the recorded outcome, not a second reservation.
  const again = await h.send('so.reserve', { orderId: orders[0].id }, { commandId: results[0].commandId })
  assert.deepEqual(again.body, results[0].body)
  await h.command('so.reserve', { orderId: orders[1].id, extra: true }, { commandId: results[0].commandId, error: 'IDEMPOTENCY' })
})

test('LARDER-006 shortages are reviewed and drafted into purchase and work orders with dates and reasons', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const q = await h.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-10-28', lines: [{ itemId: w.board.id, quantity: '14', unitPrice: '89' }] })
  await h.command('so.confirm', { orderId: q.id, version: q.version })
  let s = await h.state()
  const boards = s.shortages.find(x => x.itemId === w.board.id)
  assert.deepEqual([boards.shortage, boards.requiredBy, boards.kind], ['10', '2026-10-28', 'make'])
  assert.match(boards.reasons[0].reference, /^SO-/)
  const wo = await h.command('plan.draft', { itemId: w.board.id })
  assert.equal(wo.quantity, '10'); assert.equal(wo.requiredBy, '2026-10-28'); assert.match(wo.reason, /SO-0001 needs 10 by Oct 28, 2026/)
  await h.command('wo.release', { workOrderId: wo.id, version: wo.version })
  s = await h.state()
  const timber = s.shortages.find(x => x.itemId === w.timber.id)
  assert.equal(timber.shortage, '4'); assert.equal(timber.supplierId, w.supplier.id)
  const po = await h.command('plan.draft', { itemId: w.timber.id })
  assert.equal(po.status, 'draft'); assert.equal(po.lines[0].unitPrice, '9.5'); assert.match(po.reason, /WO-0001 needs 4/)
  assert.equal((await h.state()).shortages.find(x => x.itemId === w.timber.id), undefined)
})

test('LARDER-007 purchase approval, supplier confirmation and revised delivery are recorded', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const po = await h.command('po.draft', { supplierId: w.supplier.id, expectedDate: '2026-10-20', reason: 'Restock', lines: [{ itemId: w.timber.id, quantity: '2', unit: 'bundle', unitPrice: '9.5' }] })
  assert.equal(po.exposure, '190')
  await h.command('po.confirm', { poId: po.id, version: po.version, supplierReference: 'TT-889', source: 'phone', confirmedDate: '2026-10-22' }, { error: 'STATE' })
  const approved = await h.command('po.approve', { poId: po.id, version: po.version })
  assert.equal(approved.status, 'approved')
  const confirmed = await h.command('po.confirm', { poId: po.id, version: approved.version, supplierReference: 'TT-889', source: 'email', confirmedDate: '2026-10-22', evidence: evidence('Order acknowledgement TT-889') })
  assert.equal(confirmed.expectedDate, '2026-10-22')
  const revised = await h.command('po.revise', { poId: po.id, version: confirmed.version, expectedDate: '2026-10-29', note: 'Kiln delay' })
  assert.deepEqual(revised.history.map(x => [x.change, x.from, x.to]), [['supplier confirmed', '2026-10-20', '2026-10-22'], ['delivery revised', '2026-10-22', '2026-10-29']])
  const s = await h.state()
  const approval = s.approvals.find(a => a.subjectId === po.id)
  assert.equal(approval.decision, 'approved'); assert.equal(approval.terms.exposure, '190')
  assert.equal(avail(s, w.timber.id).expectedPurchase, '20')
})

test('LARDER-008 partial receipts record supplier lots and quarantine decisions', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const po = await h.command('po.draft', { supplierId: w.supplier.id, expectedDate: '2026-10-20', reason: 'Restock', lines: [{ itemId: w.timber.id, quantity: '20', unitPrice: '9.5' }] })
  await h.command('po.approve', { poId: po.id, version: po.version })
  const lineId = po.lines[0].id
  await h.command('receipt.create', { poId: po.id, supplierReference: 'DN-1', lines: [{ lineId, quantity: '21', locationId: w.loc.id }] }, { error: 'OVER_RECEIPT' })
  await h.command('receipt.create', { poId: po.id, supplierReference: 'DN-1', lines: [{ lineId, quantity: '8', locationId: w.loc.id, lot: 'TT-L77', inspection: 'quarantine' }] })
  let s = await h.state()
  assert.equal(s.purchaseOrders[0].status, 'part received')
  assert.deepEqual([avail(s, w.timber.id).quarantine, avail(s, w.timber.id).expectedPurchase], ['8', '12'])
  const lot = s.lots.find(l => l.code === 'TT-L77')
  assert.equal(lot.status, 'quarantined')
  await h.command('quarantine.decide', { itemId: w.timber.id, locationId: w.loc.id, lotId: lot.id, quantity: '6', decision: 'release', reason: 'Moisture 9%' })
  await h.command('quarantine.decide', { itemId: w.timber.id, locationId: w.loc.id, lotId: lot.id, quantity: '2', decision: 'reject', reason: 'Split ends' })
  s = await h.invariant()
  assert.equal(s.lots.find(l => l.id === lot.id).status, 'rejected')
  assert.equal(avail(s, w.timber.id).onHand, '12')
  assert.deepEqual(s.approvals.filter(a => a.subjectKind === 'lots').map(a => a.decision), ['released', 'rejected'])
})

