test('LARDER-010 pick, pack and partially ship against reservations; the rest stays committed', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const q = await h.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-10-28', lines: [{ itemId: w.board.id, quantity: '6', unitPrice: '89' }] })
  const order = await h.command('so.confirm', { orderId: q.id, version: q.version })
  const lineId = order.lines[0].id
  await h.command('shipment.pick', { orderId: order.id, lines: [{ lineId, locationId: w.loc.id, quantity: '5' }] }, { error: 'NOT_RESERVED' })
  const picked = await h.command('shipment.pick', { orderId: order.id, lines: [{ lineId, locationId: w.loc.id, quantity: '3' }] })
  await h.command('shipment.ship', { shipmentId: picked.id, version: picked.version, carrier: 'StarTrack' }, { error: 'STATE' })
  const packed = await h.command('shipment.pack', { shipmentId: picked.id, version: picked.version, packages: 1, weightKg: '4.2' })
  const shipped = await h.command('shipment.ship', { shipmentId: picked.id, version: packed.version, carrier: 'StarTrack', tracking: 'ST123' })
  assert.equal(shipped.status, 'shipped')
  const s = await h.invariant()
  const so = s.salesOrders[0]
  assert.equal(so.status, 'part shipped'); assert.equal(line(so, w.board.id).shipped, '3')
  assert.equal(s.reservations.reduce((n, r) => n + parse(r.quantity), 0n), parse('1'))
  assert.equal(s.shortages.find(x => x.itemId === w.board.id).shortage, '2')
})

test('LARDER-011 returns, transfers and approved counts; corrections reverse, never edit', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const worker = await h.person('sam@example.test', 'warehouse')
  const t1 = await worker.run('transfer.create', { itemId: w.board.id, fromLocationId: w.loc.id, toLocationId: w.store.id, quantity: '2', reason: 'To dispatch shelf' })
  await worker.run('transfer.create', { itemId: w.board.id, fromLocationId: w.loc.id, toLocationId: w.store.id, quantity: '3', reason: 'Too many' }, { error: 'INSUFFICIENT_STOCK' })
  const q = await h.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-10-28', lines: [{ itemId: w.board.id, quantity: '2', unitPrice: '89' }] })
  const order = await h.command('so.confirm', { orderId: q.id, version: q.version, reserve: false })
  await h.command('so.reserve', { orderId: order.id, locationId: w.store.id })
  const sh = await worker.run('shipment.pick', { orderId: order.id, lines: [{ lineId: order.lines[0].id, locationId: w.store.id, quantity: '2' }] })
  const packed = await worker.run('shipment.pack', { shipmentId: sh.id, version: sh.version, packages: 1 })
  await worker.run('shipment.ship', { shipmentId: sh.id, version: packed.version, carrier: 'Courier' })
  await worker.run('return.receive', { orderId: order.id, lineId: order.lines[0].id, quantity: '3', locationId: w.store.id, disposition: 'quarantine', reason: 'Too many' }, { error: 'RETURN_EXCEEDS' })
  const back = await worker.run('return.receive', { orderId: order.id, lineId: order.lines[0].id, quantity: '1', locationId: w.store.id, disposition: 'quarantine', reason: 'Cracked in transit' })
  // The transfer cannot be reversed: its stock left on the shipment.
  await worker.run('movement.reverse', { documentKind: 'transfers', documentId: t1.id, reason: 'Wrong shelf' }, { error: 'DEPENDENCY' })
  // A count by one person needs another's approval to adjust.
  const count = await worker.run('count.record', { itemId: w.oil.id, locationId: w.loc.id, counted: '1.75', note: 'Half-used tin' })
  assert.equal(count.variance, '-0.25')
  await worker.run('count.approve', { countId: count.id, version: count.version }, { error: 'FORBIDDEN' })
  await h.command('count.approve', { countId: count.id, version: count.version })
  let s = await h.invariant()
  assert.equal(avail(s, w.oil.id).onHand, '1.75')
  const before = s.movements.length
  // A shipment whose goods partly came back cannot be reversed past its return: that would book them twice.
  const blocked = await h.command('movement.reverse', { documentKind: 'shipments', documentId: sh.id, reason: 'Recorded against the wrong order' }, { error: 'DEPENDENCY' })
  assert.equal(blocked.error.details.blockedBy, back.reference)
  assert.equal((await h.invariant()).movements.length, before)
  await h.command('movement.reverse', { documentKind: 'returns', documentId: back.id, reason: 'Belongs to the wrong order' })
  // Reverse the shipment (recorded in error): stock and the reservation come back; the original stays.
  await h.command('movement.reverse', { documentKind: 'shipments', documentId: sh.id, reason: 'Recorded against the wrong order' })
  s = await h.invariant()
  assert.equal(s.movements.length, before + 2)
  assert.equal(avail(s, w.board.id).onHand, '4')
  assert.ok(s.movements.some(m => m.kind === 'shipment')); assert.ok(s.movements.some(m => m.kind === 'shipment-reversal'))
  assert.equal(s.salesOrders[0].lines[0].shipped, '0')
  assert.equal(s.reservations.reduce((n, r) => n + parse(r.quantity), 0n), parse('2'))
  assert.equal(s.shipments[0].status, 'reversed')
})

test('LARDER-012 handoff exports costs and invoice preparation; acknowledgements and corrections reconcile', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const q = await h.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-10-28', customerReference: 'HK-221', lines: [{ itemId: w.board.id, quantity: '2', unitPrice: '89' }] })
  const order = await h.command('so.confirm', { orderId: q.id, version: q.version })
  const sh = await h.command('shipment.pick', { orderId: order.id, lines: [{ lineId: order.lines[0].id, locationId: w.loc.id, quantity: '2' }] })
  const packed = await h.command('shipment.pack', { shipmentId: sh.id, version: sh.version, packages: 1 })
  await h.command('shipment.ship', { shipmentId: sh.id, version: packed.version, carrier: 'Courier' })
  const accounts = await h.person('ana@example.test', 'accounts')
  const batch = await accounts.run('handoff.prepare', { note: 'October' })
  const invoice = batch.lines.find(l => l.type.startsWith('Customer shipment'))
  assert.equal(invoice.amountCents, '178.00'); assert.equal(invoice.partyReference, 'HK-221')
  const csv = await (await h.request(`/api/larder/handoffs/${batch.id}.csv`, { as: accounts.cookie })).text()
  assert.match(csv, /^line,date,type,document,party/); assert.match(csv, /Harbour Kitchen Co,HK-221,BRD-WAL-L/)
  await accounts.run('handoff.prepare', {}, { error: 'NOTHING_TO_HAND_OFF' })
  const acked = await accounts.run('handoff.acknowledge', { handoffId: batch.id, version: batch.version, entries: batch.lines.map(l => ({ lineId: l.id, ledgerId: `XERO-${l.id.slice(0, 4)}`, amount: l.id === invoice.id ? '178.01' : l.amountCents })) })
  assert.equal(acked.status, 'mismatch')
  assert.ok((await h.state()).exceptions.some(x => x.kind === 'mismatch'))
  const fixed = await accounts.run('handoff.acknowledge', { handoffId: batch.id, version: acked.version, entries: [{ lineId: invoice.id, ledgerId: 'XERO-INV-1043', amount: '178.00', note: 'Typo corrected' }] })
  assert.equal(fixed.status, 'acknowledged')
  // A later reversal of a handed-off shipment arrives as a correction line pointing back.
  await h.command('movement.reverse', { documentKind: 'shipments', documentId: sh.id, reason: 'Parcel never left' })
  const next = await accounts.run('handoff.prepare', {})
  assert.equal(next.lines.length, 1)
  assert.deepEqual([next.lines[0].corrects.reference, next.lines[0].type], [batch.reference, 'Correction (reversal)'])
  // It offsets the invoice line it corrects exactly, at the order price.
  assert.equal(next.lines[0].amountCents, '-178.00')
})

test('LARDER-013 and AUTO-001 notes retain ongoing exceptions and the complete archive restores into an empty installation', async t => {
  const h = await installation(); t.after(() => h.close())
  const w = await workshop(h)
  const q = await h.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-10-28', lines: [{ itemId: w.board.id, quantity: '6', unitPrice: '89' }] })
  await h.command('so.confirm', { orderId: q.id, version: q.version })
  const po = await h.command('po.draft', { supplierId: w.supplier.id, expectedDate: '2026-01-05', reason: 'Late on purpose', lines: [{ itemId: w.timber.id, quantity: '5', unitPrice: '9.5' }] })
  await h.command('po.approve', { poId: po.id, version: po.version })
  let s = await h.state()
  assert.deepEqual([...new Set(s.exceptions.map(x => x.kind))].sort(), ['late', 'shortage'])
  const late = s.exceptions.find(x => x.kind === 'late')
  await h.command('exception.resolve', { key: late.key, note: 'Supplier rang: shipping Friday' })
  s = await h.state()
  assert.ok(s.exceptions.some(x => x.kind === 'late' && x.status === 'following up'))
  assert.equal(s.resolutions[0].note, 'Supplier rang: shipping Friday')
  const archive = await (await h.request('/api/larder/archive')).json()
  assert.equal(archive.format, 'larder-archive-v1')
  const fresh = await installation(); t.after(() => fresh.close())
  const tampered = { ...archive, movements: archive.movements.map((m, i) => i === 0 ? { ...m, quantity: '99000000' } : m) }
  const refused = await fresh.request('/api/larder/archive/restore', { method: 'POST', raw: JSON.stringify(tampered) })
  assert.equal((await refused.json()).error.code, 'CHECKSUM')
  const restored = await (await fresh.request('/api/larder/archive/restore', { method: 'POST', raw: JSON.stringify(archive) })).json()
  assert.equal(restored.ok, true, JSON.stringify(restored))
  const after = await fresh.invariant()
  assert.ok(after.exceptions.some(x => x.key === late.key && x.status === 'following up'))
  assert.equal(after.resolutions[0].note, 'Supplier rang: shipping Friday')
  assert.deepEqual(after.positions, s.positions); assert.equal(after.salesOrders[0].reference, 'SO-0001')
  assert.deepEqual(after.reservations.map(r => r.quantity), s.reservations.map(r => r.quantity))
  const opening = after.openings[0]
  assert.equal(await (await fresh.request(`/api/larder/attachments/${opening.evidence.id}`)).text(), 'Bay A count sheet, 1 Oct 2026')
  const again = await (await fresh.request('/api/larder/archive/restore', { method: 'POST', raw: JSON.stringify(archive) })).json()
  assert.equal(again.error.code, 'NOT_EMPTY')
  // The restored installation keeps working.
  const more = await fresh.command('so.quote', { customerId: w.customer.id, promiseDate: '2026-11-28', lines: [{ itemId: w.board.id, quantity: '1', unitPrice: '89' }] })
  assert.equal(more.reference, 'SO-0002')
})

