  const current = (await h.state()).purchaseOrders.find(p => p.id === po.id)
  await buyer.run('po.revise', { poId: po.id, version: current.version, lineId: po.lines[1].id, expectedDate: day(-1), note: 'Supplier overdue receipt' })
  await h.command('receipt.create', { poId: po.id, supplierReference: 'synthetic-larder-309', lines: [{ lineId: po.lines[1].id, quantity: '2', locationId: loc.id, inspection: 'accept' }] })
  s = await h.invariant(); perf = s.supplierPerformance.find(p => p.supplierId === vendors[0].id)
  assert.equal(perf.measuredDeliveries, 1); assert.equal(perf.lateDeliveries, 1)
  assert.deepEqual([perf.receipts[1].quantity, perf.receipts[1].expectedDate, perf.receipts[1].approvedDate], ['2',day(-1),day(4)])
  assert.equal(s.movements.find(m => m.kind === 'receipt' && m.status === 'available').unitCost, '1.2')
  let live = (await h.state()).purchaseOrders.find(p => p.id === po.id)
