  live = await buyer.run('po.revise', { poId: po.id, version: live.version, lineId: po.lines[0].id, expectedDate: day(-1), note: 'First delivery overdue' })
  await h.command('receipt.create', { poId: po.id, supplierReference: 'synthetic-larder-310', lines: [{ lineId: po.lines[0].id, quantity: '6', locationId: loc.id, inspection: 'quarantine', lot: 'synthetic-larder-311' }] })
  s = await h.invariant()
  assert.equal(s.purchaseOrders.find(p => p.id === po.id).expectedDate, day(8))
  assert.ok(s.exceptions.some(e => e.key === `po-late:${po.id}`), 'A later scheduled delivery must not hide an overdue quarantined line.')
  await h.command('role.set', { operatorId: buyer.id, role: 'sales' })
